const userHasActiveRootRole = `-- name: UserHasActiveRootRole :one
SELECT EXISTS (
    SELECT 1
    FROM users u
    JOIN user_roles ur ON ur.user_id = u.id
    JOIN roles r ON r.id = ur.role_id
    WHERE u.id = $1
      AND u.status = 'active'
      AND r.is_root = true
      AND r.archived_at IS NULL
) AS is_root_user
`

func (q *Queries) UserHasActiveRootRole(ctx context.Context, id uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, userHasActiveRootRole, id)
	var is_root_user bool
	err := row.Scan(&is_root_user)
	return is_root_user, err
}

const userHasEffectivePermission = `-- name: UserHasEffectivePermission :one
SELECT EXISTS (
    SELECT 1
    FROM users u
    JOIN user_roles ur ON ur.user_id = u.id
    JOIN roles r ON r.id = ur.role_id
    JOIN role_permissions rp ON rp.role_id = r.id
    JOIN permissions p ON p.id = rp.permission_id
    WHERE u.id = $1
      AND u.status = 'active'
      AND r.archived_at IS NULL
      AND p.archived_at IS NULL
      AND p.code = $2
) AS has_permission
`

type UserHasEffectivePermissionParams struct {
	ID   uuid.UUID `json:"id"`
	Code string    `json:"code"`
}

func (q *Queries) UserHasEffectivePermission(ctx context.Context, arg UserHasEffectivePermissionParams) (bool, error) {
	row := q.db.QueryRow(ctx, userHasEffectivePermission, arg.ID, arg.Code)
	var has_permission bool
	err := row.Scan(&has_permission)
	return has_permission, err
}
